    """CREATE TABLE feature_definitions (feature_definition_id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, version TEXT NOT NULL, owner TEXT NOT NULL, frequency TEXT NOT NULL, timing_semantics TEXT NOT NULL, definition JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL, UNIQUE(name, version))""",
