def immutable_trigger_sql(table: str) -> str:
    return f"CREATE TRIGGER {table}_immutable BEFORE UPDATE OR DELETE ON {table} FOR EACH ROW EXECUTE FUNCTION prevent_immutable_mutation()"


def drop_schema_sql() -> tuple[str, ...]:
    """Downgrade policy: schema-only environments may be reset, never production."""
    tables = (
        "feature_materializations", "feature_definition_versions", "audit_events", "agent_research_reviews", "agent_research_outputs", "agent_research_workflows", "investment_reviews", "investment_evidence", "investment_theses", "operational_alerts", "reconciliations", "broker_event_cursors", "fills", "oms_events", "paper_order_intents", "portfolio_positions", "risk_reservations", "risk_decisions", "accounts", "risk_policy_versions", "risk_policies", "signal_events", "signals", "model_predictions", "model_registry", "strategy_promotion_decisions", "validation_package_artifacts", "validation_packages", "quant_validation_artifacts", "golden_execution_artifacts", "walk_forward_evidence", "research_experiments", "strategy_versions", "strategy_definitions", "feature_values", "feature_definitions", "news_events", "macro_observations", "fundamental_facts", "corporate_actions", "market_bars", "market_data_provenance", "dataset_versions", "datasets", "instrument_identifiers", "instruments", "trading_calendars", "exchanges",
    )
    return tuple(f"DROP TABLE IF EXISTS {table} CASCADE" for table in tables) + ("DROP FUNCTION IF EXISTS prevent_immutable_mutation()",)
